// Kiểm tra dữ liệu WordPress gửi sang và chuẩn bị câu trả lời.
// Mọi tín hiệu kiểm tra được giữ lại trong output để xem ở tab Executions.
const receivedAt = new Date().toISOString();
const input = $input.first().json;
const body = input.body ?? {};
const headers = input.headers ?? {};
const executionId = $execution.id;
const requestId = body.request_id ?? headers['x-socialsync-request-id'] ?? null;

const trace = {
  received_at: receivedAt,
  request_id: requestId,
  plugin_version: headers['x-socialsync-version'] ?? null,
  content_type: headers['content-type'] ?? null,
  event: body.event ?? null,
};

if (body.event === 'test') {
  return [{ json: {
    http_status: 200,
    response: { ok: true, test: true, execution_id: executionId, request_id: requestId, received_at: receivedAt },
    trace,
    data: body,
  } }];
}

const problems = [];
const need = (cond, msg) => { if (!cond) problems.push(msg); };
const jobs = Array.isArray(body.jobs) ? body.jobs : [];

need(body.event === 'post_published', `event không hợp lệ: ${JSON.stringify(body.event)}`);
need(Number.isInteger(body.post_id) && body.post_id > 0, 'thiếu hoặc sai post_id');
need(['post', 'product'].includes(body.post_type), `post_type không hỗ trợ: ${JSON.stringify(body.post_type)}`);
need(typeof body.title === 'string' && body.title.trim() !== '', 'thiếu title');
need(typeof body.source_url === 'string' && /^https?:\/\//.test(body.source_url), 'thiếu hoặc sai source_url');
need(typeof body.callback_url === 'string' && /^https?:\/\//.test(body.callback_url), 'thiếu hoặc sai callback_url');
need(jobs.length > 0, 'không có lượt đồng bộ nào (jobs rỗng)');
for (const j of jobs) {
  need(Number.isInteger(j.job_id) && j.job_id > 0, `lượt thiếu job_id: ${JSON.stringify(j)}`);
  need(['facebook', 'pinterest'].includes(j.channel), `kênh không hỗ trợ: ${JSON.stringify(j.channel)}`);
}

const signals = {
  post_type: body.post_type ?? null,
  channels: jobs.map(j => j.channel),
  delays_minutes: Object.fromEntries(jobs.map(j => [j.channel, j.delay_minutes ?? 0])),
  has_image: Boolean(body.image_url),
  image_size: body.image ? `${body.image.width}x${body.image.height}` : null,
  title_chars: (body.title ?? '').length,
  content_chars: (body.content_text ?? '').length,
  excerpt_chars: (body.excerpt ?? '').length,
  categories: body.categories ?? [],
  has_price: Boolean(body.price && body.price.price),
  pinterest_will_skip: jobs.some(j => j.channel === 'pinterest') && !body.image_url,
};

if (problems.length) {
  return [{ json: {
    http_status: 422,
    response: { ok: false, execution_id: executionId, request_id: requestId, error: problems.join('; ') },
    problems,
    signals,
    trace,
    data: body,
  } }];
}

return [{ json: {
  http_status: 202,
  response: {
    ok: true,
    execution_id: executionId,
    request_id: requestId,
    received_at: receivedAt,
    accepted_jobs: jobs.map(j => j.job_id),
  },
  signals,
  trace,
  data: body,
} }];

// Nấc 3: tách mỗi lượt (kênh) thành một item và dựng nội dung theo MẪU CỐ ĐỊNH (chưa dùng AI).
// Chỉ chạy tiếp khi bước kiểm tra đã nhận bài (HTTP 202). Gói test hoặc dữ liệu lỗi dừng ở đây.
const CONFIG = {
  fb_page_id: '273106486233478',   // Fanpage Mint Shop - facebook.com/myphamcuatrang (ID công khai, không phải bí mật)
  graph_version: 'v21.0',
  utm_campaign: 'socialsync',
  fb_summary_max: 400,
  pin_title_max: 100,
  pin_description_max: 400,
};

const checked = $('Kiểm tra dữ liệu').first().json;
if (checked.http_status !== 202) {
  return [];
}
const d = checked.data;

// Lỗi giả lập CÓ CHỦ Ý để kiểm tra luồng "SocialSync - Báo lỗi": chỉ xảy ra khi tiêu đề chứa đúng chuỗi dưới.
if (String(d.title ?? '').includes('[socialsync-thu-loi]')) {
  throw new Error('Lỗi giả lập để kiểm tra luồng báo lỗi (tiêu đề chứa [socialsync-thu-loi])');
}

// Môi trường Code của n8n 2.x không có đối tượng URL (đo 2026-11-19: ReferenceError: URL is not defined),
// nên gắn tham số UTM bằng xử lý chuỗi.
const withUtm = (url, source) => {
  const hashAt = url.indexOf('#');
  const base = hashAt === -1 ? url : url.slice(0, hashAt);
  const hash = hashAt === -1 ? '' : url.slice(hashAt);
  const utm = `utm_source=${encodeURIComponent(source)}&utm_medium=social&utm_campaign=${encodeURIComponent(CONFIG.utm_campaign)}`;
  return base + (base.includes('?') ? '&' : '?') + utm + hash;
};

// Cắt ở ranh giới câu nếu được, nếu không thì ở ranh giới từ. Không cắt giữa từ.
const clip = (text, max) => {
  const t = String(text ?? '').replace(/\s+/g, ' ').trim();
  if (t.length <= max) return t;
  const cut = t.slice(0, max);
  const sentenceEnd = Math.max(cut.lastIndexOf('. '), cut.lastIndexOf('! '), cut.lastIndexOf('? '));
  if (sentenceEnd > max * 0.5) return cut.slice(0, sentenceEnd + 1);
  return cut.slice(0, Math.max(cut.lastIndexOf(' '), 1)) + '…';
};

const summary = clip(d.excerpt || d.content_text, CONFIG.fb_summary_max);
const priceLine = d.price && d.price.price_text ? `Giá: ${d.price.price_text}` : null;
const now = Date.now();

const items = d.jobs.map(job => {
  const link = withUtm(d.source_url, job.channel);
  let content;
  let facebook = null;

  if (job.channel === 'facebook') {
    const message = [d.title, summary, priceLine, `👉 Xem chi tiết: ${link}`].filter(Boolean).join('\n\n');
    content = { kind: d.image_url ? 'photo' : 'link', message, link, image_url: d.image_url || null };
    facebook = d.image_url
      ? { url: `https://graph.facebook.com/${CONFIG.graph_version}/${CONFIG.fb_page_id}/photos`, body: { url: d.image_url, caption: message, published: true } }
      : { url: `https://graph.facebook.com/${CONFIG.graph_version}/${CONFIG.fb_page_id}/feed`, body: { message, link } };
  } else {
    content = {
      title: clip(d.title, CONFIG.pin_title_max),
      description: clip([summary, priceLine].filter(Boolean).join(' '), CONFIG.pin_description_max),
      alt_text: d.image_alt || d.title,
      link,
      image_url: d.image_url || null,
    };
  }

  const delaySeconds = Math.max(0, Math.round(Number(job.delay_minutes ?? 0) * 60));
  return {
    json: {
      job_id: job.job_id,
      channel: job.channel,
      post_id: d.post_id,
      post_type: d.post_type,
      title: d.title,
      request_id: d.request_id ?? null,
      has_image: Boolean(d.image_url),
      delay_seconds: delaySeconds,
      scheduled_at: new Date(now + delaySeconds * 1000).toISOString(),
      callback_job_url: `${d.callback_url}/${job.job_id}`,
      content_source: 'template',
      content_source_reason: 'Chưa bật AI, dùng mẫu cố định',
      content,
      facebook,
    },
  };
});

// Xếp lượt theo giờ đăng tăng dần. Vòng lặp phía sau xử lý lần lượt từng lượt và chờ tới đúng giờ
// của lượt đó, nên mỗi kênh đăng theo số phút trễ riêng của nó.
items.sort((a, b) => a.json.delay_seconds - b.json.delay_seconds);
console.log('[socialsync] Thứ tự đăng', JSON.stringify(items.map(i => ({ job_id: i.json.job_id, channel: i.json.channel, delay_seconds: i.json.delay_seconds, scheduled_at: i.json.scheduled_at }))));
return items;

// Chỉ đăng những lượt WordPress đã chấp nhận chuyển sang "scheduled".
// WordPress từ chối (ví dụ 409: lượt đã xử lý rồi) => dừng lượt đó, KHÔNG đăng, tránh đăng trùng.
const source = $('AI: kiểm tra và áp nội dung').all();
const out = [];
$input.all().forEach((item, i) => {
  const s = source[i].json;
  const r = item.json;
  const ok = r.statusCode === 200 && r.body && r.body.ok === true;
  if (ok) {
    out.push({ json: { ...s, wp_scheduled: { statusCode: r.statusCode, body: r.body } }, pairedItem: { item: i } });
  } else {
    console.log(`[socialsync] Dừng lượt ${s.job_id} (${s.channel}): WordPress không chấp nhận`, JSON.stringify({ statusCode: r.statusCode ?? null, body: r.body ?? null, error: r.error ?? null }));
  }
});
return out;

// Đọc phản hồi của Facebook, chuẩn bị dữ liệu báo về WordPress.
// Mỗi bài chỉ gọi Facebook đúng 1 lần để tiết kiệm hạn mức API của app.
const s = $('Kênh Facebook?').item.json;
const r = $json;

let body = r.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { /* giữ nguyên chuỗi */ } }
const headers = r.headers ?? {};
// Facebook trả % hạn mức đã dùng trong các header này (app, Trang, doanh nghiệp).
const usage = {
  app: headers['x-app-usage'] ?? null,
  page: headers['x-page-usage'] ?? null,
  business: headers['x-business-use-case-usage'] ?? null,
};

let callback;
if (r.error && r.statusCode === undefined) {
  callback = { status: 'failed', error: `Không gọi được Facebook: ${r.error.message ?? JSON.stringify(r.error)}` };
} else if (r.statusCode >= 200 && r.statusCode < 300 && body && (body.post_id || body.id)) {
  const postId = body.post_id ?? body.id;
  callback = {
    status: 'published',
    remote_id: String(postId),
    remote_url: `https://www.facebook.com/${postId}`,
    // Bài đăng bởi app ở chế độ Live lên Trang công khai. Đã kiểm tra bằng cửa sổ ẩn danh ở lần test đầu.
    visibility: 'public',
    published_at: new Date().toISOString(),
  };
} else {
  const e = (body && body.error) || {};
  const rateLimited = [4, 17, 32, 613, 80001].includes(Number(e.code));
  callback = {
    status: 'failed',
    error: `Facebook từ chối (HTTP ${r.statusCode}${e.code ? `, mã ${e.code}` : ''}${e.error_subcode ? `/${e.error_subcode}` : ''}${rateLimited ? ', HẾT HẠN MỨC GỌI API' : ''}): ${e.message ?? JSON.stringify(body)}${e.fbtrace_id ? ` [fbtrace_id ${e.fbtrace_id}]` : ''}`,
  };
}
callback.execution_id = $execution.id;

return { json: { ...s, callback, facebook_result: { statusCode: r.statusCode ?? null, body, usage } } };

// Đọc phản hồi của Make (scenario "SocialSync - Pinterest"), chuẩn bị dữ liệu báo về WordPress.
// Khối "Webhook response" bên Make trả: {"ok": true, "pin_id": "...", "request_id": "...", "job_id": ...}
const s = $('Pinterest: có ảnh?').item.json;
const r = $json;

let body = r.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { /* giữ nguyên chuỗi */ } }
const snippet = (v) => {
  const t = typeof v === 'string' ? v : JSON.stringify(v);
  return t && t.length > 300 ? t.slice(0, 300) + '…' : t;
};
const pinId = body && typeof body === 'object' ? String(body.pin_id ?? '').trim() : '';

let callback;
if (r.error && r.statusCode === undefined) {
  const msg = r.error.message ?? JSON.stringify(r.error);
  const hint = /MAKE_PINTEREST_WEBHOOK|invalid url/i.test(msg)
    ? ' (chưa có MAKE_PINTEREST_WEBHOOK trong .env, hoặc chưa chạy lại scripts/n8n-nap-luong.ps1)'
    : '';
  callback = { status: 'failed', error: `Không gọi được Make: ${msg}${hint}` };
} else if (r.statusCode === 200 && /^\d+$/.test(pinId)) {
  callback = {
    status: 'published',
    remote_id: pinId,
    remote_url: `https://www.pinterest.com/pin/${pinId}/`,
    // Make dùng app Pinterest đã được duyệt đầy đủ. Pin thử đầu tiên xem được khi chưa đăng nhập (2026-11-19).
    visibility: 'public',
    published_at: new Date().toISOString(),
  };
} else {
  let hint = '';
  if (typeof body === 'string' && body.trim() === 'Accepted') {
    hint = ' (Make chưa trả kết quả: scenario đang TẮT, hoặc thiếu khối "Webhook response")';
  } else if (r.statusCode === 200) {
    hint = ' (Make trả về nhưng không có pin_id dạng số: kiểm tra nội dung khối "Webhook response")';
  }
  callback = { status: 'failed', error: `Make/Pinterest không tạo được Pin (HTTP ${r.statusCode}): ${snippet(body)}${hint}` };
}
callback.execution_id = $execution.id;

return { json: { ...s, callback, pinterest_result: { statusCode: r.statusCode ?? null, body, request_id_echo: body && body.request_id ? body.request_id : null } } };

// Pinterest bắt buộc mỗi Pin có ảnh.
const s = $json;
return { json: { ...s, callback: { status: 'skipped', error: 'Bài không có ảnh đại diện, Pinterest bắt buộc có ảnh', execution_id: $execution.id } } };

// Chạy một lần khi vòng lặp xong mọi kênh: gom kết quả WordPress trả về cho từng lượt.
const results = $input.all().map(i => ({
  statusCode: i.json.statusCode ?? null,
  job_id: i.json.body?.job_id ?? null,
  status_before: i.json.body?.status_before ?? null,
  status_after: i.json.body?.status_after ?? null,
  error: i.json.body?.error ?? i.json.error?.message ?? null,
}));
console.log('[socialsync] Tổng kết', JSON.stringify(results));
return [{ json: { total: results.length, all_ok: results.every(r => r.statusCode === 200), results } }];

// Dựng MỘT yêu cầu gửi Claude cho cả bài: Claude viết nội dung cho mọi kênh trong một lần gọi.
// Giá và link KHÔNG để AI viết: bước sau tự gắn từ dữ liệu WordPress, nên không thể bị bịa.
const AI = {
  model: 'claude-opus-5-5',
  effort: 'medium',
  max_tokens: 8000,
  content_max_chars: 4000,
};

const items = $input.all();
const d = $('Kiểm tra dữ liệu').first().json.data;
const channels = items.map(i => i.json.channel);

const SYSTEM = [
  'Bạn là biên tập viên mạng xã hội cho một cửa hàng trực tuyến ở Việt Nam bán sản phẩm sức khỏe và làm đẹp.',
  'Từ dữ liệu một bài viết hoặc sản phẩm vừa đăng trên website, bạn viết nội dung đăng Facebook Fanpage và Pinterest.',
  '',
  'Nguyên tắc chung:',
  '- Tiếng Việt có dấu, giọng thân thiện, rõ ràng, đáng tin.',
  '- Chỉ dùng thông tin có trong dữ liệu. Không bịa thành phần, công dụng, số liệu, khuyến mãi.',
  '- Không ghi giá và không ghi đường link: hệ thống tự gắn giá và link sau.',
  '- Với sản phẩm sức khỏe: không khẳng định chữa, điều trị hay phòng ngừa bệnh; không so sánh với thuốc; không hứa hẹn kết quả (ví dụ "100%", "khỏi hẳn", "cam kết").',
  '- Nếu là thực phẩm bảo vệ sức khỏe hoặc thực phẩm chức năng, kết thúc facebook.message bằng đúng câu: "Thực phẩm này không phải là thuốc, không có tác dụng thay thế thuốc chữa bệnh."',
  '',
  'Facebook:',
  '- facebook.message: 60 đến 150 từ, câu đầu là câu mở gây chú ý, chia 2 đến 4 đoạn ngắn, tối đa 3 emoji. Không có hashtag trong message.',
  '- facebook.hashtags: 3 đến 5 hashtag liên quan, mỗi hashtag bắt đầu bằng #, viết liền không dấu.',
  '',
  'Pinterest:',
  '- pinterest.title: tối đa 90 ký tự, chứa từ khóa chính người dùng hay tìm.',
  '- pinterest.description: 150 đến 450 ký tự, viết như một mô tả tìm kiếm tự nhiên, có 2 đến 3 từ khóa, tối đa 3 hashtag.',
  '- pinterest.alt_text: tối đa 150 ký tự, mô tả chủ đề ảnh minh họa dựa trên tiêu đề, không bịa chi tiết hình ảnh.',
].join('\n');

const clipText = (t, max) => { const s = String(t ?? '').replace(/\s+/g, ' ').trim(); return s.length > max ? s.slice(0, max) + '…' : s; };
const post = {
  loai_noi_dung: d.post_type === 'product' ? 'Sản phẩm' : 'Bài viết',
  tieu_de: d.title,
  tom_tat: d.excerpt || null,
  noi_dung: clipText(d.content_text, AI.content_max_chars),
  danh_muc: d.categories ?? [],
  co_gia: Boolean(d.price && d.price.price_text),
  kenh_can_viet: channels,
};

const schema = {
  type: 'object',
  properties: {
    facebook: {
      type: 'object',
      properties: {
        message: { type: 'string' },
        hashtags: { type: 'array', items: { type: 'string' } },
      },
      required: ['message', 'hashtags'],
      additionalProperties: false,
    },
    pinterest: {
      type: 'object',
      properties: {
        title: { type: 'string' },
        description: { type: 'string' },
        alt_text: { type: 'string' },
      },
      required: ['title', 'description', 'alt_text'],
      additionalProperties: false,
    },
  },
  required: ['facebook', 'pinterest'],
  additionalProperties: false,
};

const request_body = {
  model: AI.model,
  max_tokens: AI.max_tokens,
  // Nếu Claude Opus 5.5 từ chối vì bộ lọc an toàn, API tự chạy lại trên mô hình dự phòng (beta server-side-fallback).
  fallbacks: 'default',
  output_config: { effort: AI.effort, format: { type: 'json_schema', schema } },
  system: SYSTEM,
  messages: [{ role: 'user', content: 'Dữ liệu bài vừa đăng trên website (JSON):\n' + JSON.stringify(post, null, 2) }],
};

console.log('[socialsync] Gửi Claude', JSON.stringify({ request_id: d.request_id ?? null, post_id: d.post_id, model: AI.model, effort: AI.effort, channels, content_chars: post.noi_dung.length }));
return [{ json: { request_body, ai_started_ms: Date.now(), channels } }];

// Kiểm tra kết quả Claude. Đạt thì thay nội dung mẫu bằng nội dung AI; không đạt thì GIỮ nội dung mẫu
// và ghi rõ lý do vào content_source_reason. Lỗi AI không bao giờ làm hỏng việc đăng bài.
const CONFIG = { fb_page_id: '273106486233478', graph_version: 'v21.0' };
const DISCLAIMER = 'Thực phẩm này không phải là thuốc, không có tác dụng thay thế thuốc chữa bệnh.';
// Các cụm từ quảng cáo sức khỏe bị cấm hoặc rủi ro cao. Bỏ câu cảnh báo bắt buộc ra trước khi dò.
const BANNED = /(chữa\s+(khỏi|bệnh|trị|dứt)|điều\s+trị|đặc\s+trị|khỏi\s+hẳn|khỏi\s+bệnh|thay\s+thế\s+thuốc|100\s*%|cam\s+kết|thần\s+dược)/i;

const req = $('AI: dựng yêu cầu').first().json;
const templ = $('Tách lượt và dựng nội dung').all();
const d = $('Kiểm tra dữ liệu').first().json.data;
const r = $input.first().json;
const aiMs = Date.now() - req.ai_started_ms;

let body = r.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { /* giữ chuỗi */ } }
const usage = body && body.usage ? body.usage : {};
const modelUsed = body && body.model ? body.model : null;

const problems = [];
let ai = null;
if (r.error && r.statusCode === undefined) {
  problems.push(`không gọi được Claude: ${r.error.message ?? JSON.stringify(r.error)}`);
} else if (r.statusCode !== 200) {
  const e = (body && body.error) || {};
  problems.push(`Claude trả HTTP ${r.statusCode}${e.type ? ` (${e.type})` : ''}: ${e.message ?? String(JSON.stringify(body)).slice(0, 300)}${r.statusCode === 401 ? ' - kiểm tra ANTHROPIC_API_KEY trong .env rồi chạy lại scripts/n8n-nap-luong.ps1' : ''}`);
} else if (body.stop_reason !== 'end_turn') {
  problems.push(`Claude dừng với stop_reason=${body.stop_reason}${body.stop_details ? ` (${JSON.stringify(body.stop_details)})` : ''}`);
} else {
  const text = (body.content ?? []).filter(b => b.type === 'text').map(b => b.text).join('');
  try { ai = JSON.parse(text); } catch (e) { problems.push(`kết quả không phải JSON: ${text.slice(0, 200)}`); }
}

if (ai) {
  const fb = ai.facebook ?? {};
  const pin = ai.pinterest ?? {};
  const len = s => String(s ?? '').trim().length;
  if (len(fb.message) < 80 || len(fb.message) > 2000) problems.push(`facebook.message dài ${len(fb.message)} ký tự (cần 80-2000)`);
  if (!Array.isArray(fb.hashtags) || fb.hashtags.length > 8) problems.push('facebook.hashtags không hợp lệ');
  if (len(pin.title) < 10 || len(pin.title) > 100) problems.push(`pinterest.title dài ${len(pin.title)} ký tự (cần 10-100)`);
  if (len(pin.description) < 50 || len(pin.description) > 500) problems.push(`pinterest.description dài ${len(pin.description)} ký tự (cần 50-500)`);
  if (len(pin.alt_text) < 5 || len(pin.alt_text) > 500) problems.push(`pinterest.alt_text dài ${len(pin.alt_text)} ký tự`);
  const allText = [fb.message, ...(fb.hashtags ?? []), pin.title, pin.description, pin.alt_text].join(' ').split(DISCLAIMER).join(' ');
  const banned = allText.match(BANNED);
  if (banned) problems.push(`có cụm từ quảng cáo sức khỏe bị cấm: "${banned[0]}"`);
}

const useAi = ai && problems.length === 0;
const nChannels = templ.length;
const reason = useAi
  ? `Claude viết (${modelUsed}, 1 lần gọi cho ${nChannels} kênh, ${aiMs} ms)`
  : `Dùng mẫu cố định vì AI không đạt: ${problems.join('; ')}`.slice(0, 250);
console.log('[socialsync] Kết quả AI', JSON.stringify({ use_ai: useAi, problems, model: modelUsed, usage, ai_ms: aiMs, status: r.statusCode ?? null, stop_reason: body?.stop_reason ?? null }));

const priceLine = d.price && d.price.price_text ? `Giá: ${d.price.price_text}` : null;
return templ.map((item, i) => {
  const s = item.json;
  const out = {
    ...s,
    content_source: useAi ? 'ai' : 'template',
    content_source_reason: reason,
    model: modelUsed,
    tokens_in: usage.input_tokens ?? null,
    tokens_out: usage.output_tokens ?? null,
    ai_ms: aiMs,
    ai_problems: problems,
  };
  if (useAi) {
    if (s.channel === 'facebook') {
      const link = s.content.link;
      const tags = (ai.facebook.hashtags ?? []).map(t => String(t).trim()).filter(Boolean).map(t => t.startsWith('#') ? t : '#' + t).join(' ');
      const message = [ai.facebook.message.trim(), priceLine, `👉 Xem chi tiết: ${link}`, tags].filter(Boolean).join('\n\n');
      out.content = { ...s.content, message };
      out.facebook = d.image_url
        ? { url: `https://graph.facebook.com/${CONFIG.graph_version}/${CONFIG.fb_page_id}/photos`, body: { url: d.image_url, caption: message, published: true } }
        : { url: `https://graph.facebook.com/${CONFIG.graph_version}/${CONFIG.fb_page_id}/feed`, body: { message, link } };
    } else {
      out.content = {
        ...s.content,
        title: ai.pinterest.title.trim().slice(0, 100),
        description: [ai.pinterest.description.trim(), priceLine].filter(Boolean).join(' ').slice(0, 500),
        alt_text: ai.pinterest.alt_text.trim().slice(0, 500),
      };
    }
  }
  return { json: out, pairedItem: { item: i } };
});
